import{_ as a,o,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Plan — Update Workspace Member Role (FR 3.4.20)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/plan.md","filePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/plan.md"}'),c={name:"feature/agency-workspace/3-4-20-update-workspace-member-role/plan.md"};function d(n,e,s,l,i,h){return o(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="plan-—-update-workspace-member-role-fr-3-4-20" tabindex="-1">Plan — Update Workspace Member Role (FR 3.4.20) <a class="header-anchor" href="#plan-—-update-workspace-member-role-fr-3-4-20" aria-label="Permalink to &quot;Plan — Update Workspace Member Role (FR 3.4.20)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho MANAGER đổi role của 1 member trong Workspace, kèm 2 guard (mất MANAGER cuối + trùng MANAGER).</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>WorkspaceServiceImpl.updateMemberRole(workspaceId, memberId, newRole)</code></td></tr><tr><td>File đã có</td><td><code>WorkspaceController</code> (<code>PATCH /{workspaceId}/members/{memberId}/role</code>), <code>UpdateMemberRoleRequest { role }</code>, <code>WorkspaceMemberRepository.countByWorkspaceIdAndRoleAndIsActiveTrue</code>, helper <code>assertNotLastManager</code> (dùng chung 3.4.16/3.4.21)</td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/workspaces/{workspaceId}/members/{memberId}/role</span></span>
<span class="line"><span>{ &quot;role&quot;: &quot;MANAGER|CREATOR|CLIENT&quot; }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;WorkspaceMemberResponse&gt;</span></span></code></pre></div><p>Bảo vệ bởi <code>@RequireRole({MemberRole.MANAGER})</code>. Không lệch spec.md.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li><strong>UPDATE</strong> <code>workspace_members.role</code> của member target (đã active, thuộc đúng <code>workspaceId</code>). Không thêm cột, không migration.</li><li>2 guard dùng chung pattern với 3.4.16 (Leave) và 3.4.21 (Remove) — cùng method <code>assertNotLastManager</code>.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li><code>@RequireRole(MANAGER)</code> chặn (aspect, check membership theo <code>user.getWorkspaceId()</code>).</li><li>Tìm member theo <code>memberId</code>, filter <code>workspaceId</code> khớp + <code>isActive=true</code> → không có → 404 <code>NOT_FOUND</code>.</li><li><strong>Giảm quyền:</strong> nếu <code>member.role == MANAGER</code> và <code>newRole != MANAGER</code> → gọi <code>assertNotLastManager</code> (đếm active MANAGER &lt;=1 → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>).</li><li><strong>Thăng quyền:</strong> nếu <code>newRole == MANAGER</code> và <code>member.role != MANAGER</code> → đếm active MANAGER; nếu &gt;0 → 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li>Set <code>member.role = newRole</code>, <code>updatedAt = now</code>, save.</li><li>Trả <code>WorkspaceMemberResponse</code> (kèm fullName/email từ <code>User</code> nếu có <code>userId</code>).</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>WorkspaceMember</code>, <code>countByWorkspaceIdAndRoleAndIsActiveTrue</code> (đã có)</td></tr><tr><td>Bị chặn</td><td><code>View Workspace Members</code> (3.4.18) — hiển thị role mới sau khi update</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Dùng chung <code>assertNotLastManager</code> với 3.4.16/3.4.21</strong> — sửa logic guard 1 chỗ ảnh hưởng cả 3 FR, cần test lại đủ 3 FR khi đổi.</li><li><strong><code>@RequireRole</code> check theo <code>user.getWorkspaceId()</code></strong> (workspace active của principal), không theo <code>@PathVariable workspaceId</code> — nếu member muốn đổi role ở workspace khác với workspace đang active, aspect sẽ chặn nhầm. Đây là giới hạn có sẵn của annotation, chấp nhận vì FE luôn gọi trong context workspace đang thao tác.</li><li><strong>No-op đổi role cùng giá trị</strong> — không có guard chặn, trả 200 bình thường. Cân nhắc thêm check idempotent nếu FE cần tín hiệu &quot;không có gì thay đổi&quot;.</li></ul>`,15)])])}const u=a(c,[["render",d]]);export{m as __pageData,u as default};
